 *
 * SR-09: every item stays inside laboratory conduct. Nothing here describes
 * obtaining or handling a hazardous substance outside the virtual laboratory.
 */
class SafetyTierQuestionSeeder extends Seeder
{
    public function run(): void
    {
        $questions = [
            ['tier_number' => 1, 'prompt' => "Before you begin any practical work in the laboratory, what must you do first?", 'options' => ["Put on safety goggles and tie back long hair", "Taste a small amount of each chemical", "Open every reagent bottle to check the smell", "Switch on the gas tap"], 'correct_option' => 0, 'explanation' => "Eye protection goes on before any apparatus is touched. Tasting or smelling reagents is never a laboratory procedure."],
            ['tier_number' => 1, 'prompt' => "You may eat or drink in the laboratory:", 'options' => ["Never", "During a long experiment", "If the food is covered", "Only water"], 'correct_option' => 0, 'explanation' => "Food and drink are never permitted. Contaminated hands and open containers both carry chemicals to the mouth."],
            ['tier_number' => 1, 'prompt' => "A glass beaker cracks in your hand while you are carrying it. What do you do?", 'options' => ["Tell the teacher at once and leave the pieces alone", "Sweep the pieces into your palm", "Put the pieces in the paper bin", "Wash the pieces in the sink"], 'correct_option' => 0, 'explanation' => "Broken glass is reported, not handled. It goes into a labelled broken-glass bin by the teacher, never a paper bin or a sink."],
            ['tier_number' => 1, 'prompt' => "Why must you never work alone in a laboratory?", 'options' => ["Nobody could help or call for help in an accident", "It is more enjoyable with friends", "Equipment must be shared", "Experiments take less time"], 'correct_option' => 0, 'explanation' => "A laboratory accident needs a second person to raise the alarm. Working alone is prohibited for that reason alone."],
            ['tier_number' => 1, 'prompt' => "Long hair in the laboratory must be:", 'options' => ["Tied back", "Left loose", "Covered in oil", "Cut short"], 'correct_option' => 0, 'explanation' => "Loose hair reaches flames and apparatus. It is tied back before work begins."],
            ['tier_number' => 1, 'prompt' => "Where should school bags and coats be kept during practical work?", 'options' => ["Away from the bench, in the place provided", "Under your stool", "On the bench beside you", "On your lap"], 'correct_option' => 0, 'explanation' => "Bags on or under a bench are a trip hazard and get contaminated. They go in the storage place provided."],
            ['tier_number' => 1, 'prompt' => "You finish an experiment. What is the correct order?", 'options' => ["Clean apparatus, return it, then wash your hands", "Wash your hands, then leave", "Leave apparatus for the next class", "Pour everything down the sink"], 'correct_option' => 0, 'explanation' => "Apparatus is cleaned and returned, and hands are washed last, after all contact with chemicals has ended."],
            ['tier_number' => 1, 'prompt' => "Running in the laboratory is forbidden because:", 'options' => ["A collision near glassware or a flame causes serious injury", "It disturbs other students", "It wastes time", "The floor is expensive"], 'correct_option' => 0, 'explanation' => "The hazard is collision with hot, sharp or chemical-bearing apparatus, not the noise."],
            ['tier_number' => 1, 'prompt' => "An unlabelled bottle is found on the bench. You should:", 'options' => ["Report it to the teacher and not use it", "Smell it to identify the contents", "Use it if it looks like water", "Pour it into the sink"], 'correct_option' => 0, 'explanation' => "An unidentified substance is never used, smelt or disposed of by a student. It is reported."],
            ['tier_number' => 1, 'prompt' => "The laboratory fire exit and first aid kit positions should be known:", 'options' => ["Before any practical work begins", "After the first accident", "Only by the teacher", "Only during a fire drill"], 'correct_option' => 0, 'explanation' => "Knowing the exits and the kit position is part of preparing to work, not a response to an emergency."],
            ['tier_number' => 2, 'prompt' => "How do you smell a gas in a test tube, when an experiment requires it?", 'options' => ["Waft the vapour towards you with your hand", "Put the tube under your nose and inhale", "Hold the tube to one nostril", "Shake the tube then inhale deeply"], 'correct_option' => 0, 'explanation' => "Wafting brings a dilute sample to the nose. Inhaling directly over a tube can deliver a harmful concentration."],
            ['tier_number' => 2, 'prompt' => "Concentrated acid is to be diluted. What is the correct procedure?", 'options' => ["Add the acid slowly to water, stirring", "Add water to the acid quickly", "Mix equal volumes at once", "Heat the acid first, then add water"], 'correct_option' => 0, 'explanation' => "Acid is added to water so that the heat released is absorbed by the larger volume. Water into concentrated acid can boil and spit."],
            ['tier_number' => 2, 'prompt' => "Acid touches your skin. The first action is:", 'options' => ["Flood the area with cold running water", "Rub the area dry", "Apply a strong base to neutralise it", "Cover it and continue working"], 'correct_option' => 0, 'explanation' => "Flooding with water dilutes and removes the acid. Neutralising on skin releases heat and causes further injury."],
            ['tier_number' => 2, 'prompt' => "A reagent bottle has been poured from. The remainder should be:", 'options' => ["Never returned to the stock bottle", "Poured back to avoid waste", "Mixed with the next reagent", "Left in the measuring cylinder"], 'correct_option' => 0, 'explanation' => "Returning a poured reagent contaminates the whole stock bottle. The excess is disposed of as instructed."],
            ['tier_number' => 2, 'prompt' => "Which label tells you a substance can destroy skin and eyes on contact?", 'options' => ["Corrosive", "Flammable", "Oxidising", "Harmful to the environment"], 'correct_option' => 0, 'explanation' => "The corrosive pictogram, a liquid damaging a surface and a hand, marks substances that destroy living tissue."],
            ['tier_number' => 2, 'prompt' => "Chemicals are carried between benches:", 'options' => ["In a rack or with two hands, close to the body", "In one hand above shoulder height", "By passing them to a classmate", "In a pocket"], 'correct_option' => 0, 'explanation' => "A container held low, supported, and close to the body survives a stumble. Nothing is carried overhead."],
            ['tier_number' => 2, 'prompt' => "Pipetting by mouth is:", 'options' => ["Never permitted", "Permitted for water", "Permitted for dilute solutions", "Permitted with a clean pipette"], 'correct_option' => 0, 'explanation' => "A pipette filler is always used. Mouth pipetting has caused fatal poisonings and is prohibited outright."],
            ['tier_number' => 2, 'prompt' => "Gloves are worn when handling corrosive liquids. After the work they should be:", 'options' => ["Removed without touching the outer surface, then hands washed", "Washed and reused immediately", "Kept on until the next lesson", "Put in your pocket"], 'correct_option' => 0, 'explanation' => "The outer surface carries the chemical. Gloves come off inside out and hands are washed afterwards."],
            ['tier_number' => 2, 'prompt' => "Mixing a cleaning product containing bleach with one containing ammonia:", 'options' => ["Releases a toxic gas and must never be done", "Makes a stronger cleaner", "Is safe in small amounts", "Produces only water"], 'correct_option' => 0, 'explanation' => "That combination releases chloramine vapour. Household chemicals are never mixed, in the laboratory or at home."],
            ['tier_number' => 2, 'prompt' => "A solid chemical is weighed out. It is placed:", 'options' => ["On a watch glass or weighing boat, never directly on the pan", "Directly on the balance pan", "On a paper towel", "In your palm"], 'correct_option' => 0, 'explanation' => "A weighing vessel keeps the balance clean and lets the whole sample be transferred without loss."],
            ['tier_number' => 3, 'prompt' => "A test tube is heated over a Bunsen burner. The mouth of the tube must point:", 'options' => ["Away from yourself and from everyone else", "Towards your face to observe the change", "Towards the ceiling", "Towards the teacher"], 'correct_option' => 0, 'explanation' => "Heated liquid can spit out of the tube. The opening faces a direction where no person stands."],
            ['tier_number' => 3, 'prompt' => "The correct flame for general heating is:", 'options' => ["The blue roaring flame, with the air hole open", "The yellow luminous flame", "The flame with the air hole shut", "The smallest possible flame"], 'correct_option' => 0, 'explanation' => "The blue flame is hotter and leaves no soot. The yellow flame is the safety flame, used between heatings."],
            ['tier_number' => 3, 'prompt' => "Between heatings a Bunsen burner should be:", 'options' => ["Left on the yellow safety flame or turned off", "Left on the blue flame", "Moved to the floor", "Covered with a cloth"], 'correct_option' => 0, 'explanation' => "The visible yellow flame tells everyone the burner is alight. An unattended blue flame is nearly invisible."],
            ['tier_number' => 3, 'prompt' => "A beaker has just been heated. How do you move it?", 'options' => ["With tongs or a cloth, after checking it is not hot enough to crack", "With bare hands if it looks cool", "By pouring cold water on it first", "By sliding it across the bench"], 'correct_option' => 0, 'explanation' => "Hot glass looks exactly like cold glass. Tongs are used, and sudden cooling cracks the glass."],
            ['tier_number' => 3, 'prompt' => "Clothing catches fire in the laboratory. The response is:", 'options' => ["Stop, drop and roll, or use the fire blanket", "Run to the corridor for help", "Pour a beaker of water over the flames", "Fan the flames out"], 'correct_option' => 0, 'explanation' => "Smothering the flames stops the supply of air. Running feeds the fire and spreads it."],
            ['tier_number' => 3, 'prompt' => "A small fire starts in a beaker of flammable liquid. The first action is:", 'options' => ["Cover it to cut off the air, and call the teacher", "Carry the beaker to the sink", "Blow the flame out", "Add more liquid"], 'correct_option' => 0, 'explanation' => "Smothering removes the oxygen. Carrying a burning vessel spreads the fire along your route."],
            ['tier_number' => 3, 'prompt' => "Flammable liquids such as ethanol are kept:", 'options' => ["Away from any open flame, and the burner is turned off first", "Beside the Bunsen burner for convenience", "In an open beaker", "Near a window in sunlight"], 'correct_option' => 0, 'explanation' => "Ethanol vapour travels along the bench and ignites at a distance. The flame is out before the bottle is opened."],
            ['tier_number' => 3, 'prompt' => "Which extinguisher class is used on an electrical fire?", 'options' => ["Carbon dioxide", "Water", "Foam on its own", "Sand only"], 'correct_option' => 0, 'explanation' => "Carbon dioxide leaves no conducting residue. Water on live equipment carries current to the person holding the hose."],
            ['tier_number' => 3, 'prompt' => "Hot apparatus is left to cool:", 'options' => ["On a heatproof mat, where it will not be touched", "On the wooden bench top", "In a sink of cold water", "On a paper towel"], 'correct_option' => 0, 'explanation' => "A heatproof mat protects the bench and marks the apparatus as hot. Cold water cracks hot glass."],
            ['tier_number' => 3, 'prompt' => "A thermometer breaks and liquid spills from it. You should:", 'options' => ["Report it at once and keep everyone away from the spill", "Wipe it up with a paper towel", "Push the liquid together with your finger", "Wash it down the sink"], 'correct_option' => 0, 'explanation' => "A broken thermometer is reported. The spill is cleared by the teacher with the proper kit, never by hand."],
            ['tier_number' => 4, 'prompt' => "A chemical splashes into a classmate's eye. What is done first?", 'options' => ["Rinse the open eye with running water for at least 10 minutes and send for help", "Let the eye close so it can rest", "Rub the eye with a clean cloth", "Apply an eye ointment"], 'correct_option' => 0, 'explanation' => "Prolonged rinsing of the open eye dilutes and removes the chemical. Rubbing drives it further in."],
            ['tier_number' => 4, 'prompt' => "How long should a chemical splash on the skin be rinsed?", 'options' => ["At least 10 minutes under cold running water", "A few seconds", "Until it stops stinging", "It should not be rinsed"], 'correct_option' => 0, 'explanation' => "Ten minutes or more is the standard, because dilution continues to matter after the pain has stopped."],
            ['tier_number' => 4, 'prompt' => "Someone swallows a laboratory chemical. You should:", 'options' => ["Tell the teacher at once and not make the person vomit", "Make the person vomit", "Give milk to neutralise it", "Wait to see if symptoms appear"], 'correct_option' => 0, 'explanation' => "Induced vomiting sends a corrosive substance through the throat a second time. Qualified help is called immediately."],
            ['tier_number' => 4, 'prompt' => "A minor cut from glassware is treated by:", 'options' => ["Letting it bleed briefly, rinsing with water, then a dressing from the first aid kit", "Covering it with your sleeve", "Applying antiseptic alcohol into the cut", "Ignoring it until the lesson ends"], 'correct_option' => 0, 'explanation' => "Brief bleeding carries fragments out. The wound is then rinsed and dressed, and the incident reported."],
            ['tier_number' => 4, 'prompt' => "A small burn on the hand from hot apparatus should be:", 'options' => ["Cooled under running water for at least 10 minutes", "Covered in ointment at once", "Wrapped tightly in cloth", "Rubbed with ice"], 'correct_option' => 0, 'explanation' => "Cooling limits how deep the burn goes. Ice damages the tissue further and ointment traps heat."],
            ['tier_number' => 4, 'prompt' => "Every laboratory accident, however small, must be:", 'options' => ["Reported to the teacher and recorded", "Kept quiet if nobody was hurt", "Reported only if a chemical was spilt", "Reported at the end of term"], 'correct_option' => 0, 'explanation' => "The record is what prevents the same accident happening again. Severity is not the student's judgement to make."],
            ['tier_number' => 4, 'prompt' => "During a fire alarm in the laboratory you should:", 'options' => ["Turn off your burner if it is safe, then leave by the nearest exit without collecting belongings", "Finish the experiment first", "Collect your bag and then leave", "Wait at your bench for instructions"], 'correct_option' => 0, 'explanation' => "Gas off, then out. Belongings are left behind because collecting them costs the time that matters."],
            ['tier_number' => 4, 'prompt' => "The eyewash station and safety shower should be located:", 'options' => ["Before the practical begins, by everyone in the room", "By the teacher only", "When an accident happens", "At the end of the lesson"], 'correct_option' => 0, 'explanation' => "In an eye splash there is no time to search. The position is known in advance."],
            ['tier_number' => 4, 'prompt' => "A classmate has inhaled an irritating gas. The first action is:", 'options' => ["Move them to fresh air and call the teacher", "Give them water to drink", "Ask them to hold their breath", "Have them lie face down"], 'correct_option' => 0, 'explanation' => "Removing the person from the source stops the exposure. Nothing is given by mouth."],
            ['tier_number' => 4, 'prompt' => "Who may clear a large chemical spill?", 'options' => ["The teacher or a trained adult with the spill kit", "Any student with gloves", "The student who caused it", "Nobody, it evaporates"], 'correct_option' => 0, 'explanation' => "A large spill needs the correct absorbent and disposal route. Students evacuate the area and report it."],
        ];

        foreach ($questions as $question) {
            SafetyTierQuestion::updateOrCreate(
                ['tier_number' => $question['tier_number'], 'prompt' => $question['prompt']],
                $question
            );
